css:
@keyframes slide-in {
  from {
    opacity: 0;
    transform: translateX(-40px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes fade {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.banner {
  margin: 24px;
  padding: 14px 18px;
  border-radius: 8px;
  background-color: #18181b;
  color: #fafafa;
  font-family: system-ui, sans-serif;
  animation: slide-in 600ms ease-out;
}

@media (prefers-reduced-motion: reduce) {
  .banner {
    animation: fade 600ms ease-out;
  }
}
